ValidationRule.errorConditionFormula:
AND(
  ISPICKVAL(Status, "Convertido"),
  /* Si NO existe ningún medio válido => ERROR */
  NOT(
    OR(
      /* Medio 1 válido */
      AND(
        LEA_Principal1__c = TRUE,
        OR(
          ISPICKVAL(LEA_Via_de_Contacto1__c, "TELÉFONO FIJO"),
          ISPICKVAL(LEA_Via_de_Contacto1__c, "TELÉFONO MÓVIL"),
          ISPICKVAL(LEA_Via_de_Contacto1__c, "TELÉFONO TRABAJO"),
          ISPICKVAL(LEA_Via_de_Contacto1__c, "MÓVIL EN EL EXTERIOR")
        ),
        NOT(ISBLANK(LEA_Numero_Correo1__c))
      ),

      /* Medio 2 válido */
      AND(
        LEA_Principal2__c = TRUE,
        OR(
          ISPICKVAL(LEA_Via_de_Contacto2__c, "TELÉFONO FIJO"),
          ISPICKVAL(LEA_Via_de_Contacto2__c, "TELÉFONO MÓVIL"),
          ISPICKVAL(LEA_Via_de_Contacto2__c, "TELÉFONO TRABAJO"),
          ISPICKVAL(LEA_Via_de_Contacto2__c, "MÓVIL EN EL EXTERIOR")
        ),
        NOT(ISBLANK(LEA_Numero_Correo2__c))
      ),

      /* Medio 3 válido */
      AND(
        LEA_Principal3__c = TRUE,
        OR(
          ISPICKVAL(LEA_Via_de_Contacto3__c, "TELÉFONO FIJO"),
          ISPICKVAL(LEA_Via_de_Contacto3__c, "TELÉFONO MÓVIL"),
          ISPICKVAL(LEA_Via_de_Contacto3__c, "TELÉFONO TRABAJO"),
          ISPICKVAL(LEA_Via_de_Contacto3__c, "MÓVIL EN EL EXTERIOR")
        ),
        NOT(ISBLANK(LEA_Numero_Correo3__c))
      )
    )
  )
)
